import org.apache.pdfbox.Loader;
import org.apache.pdfbox.contentstream.PDFGraphicsStreamEngine;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.graphics.image.PDImage;
import org.apache.pdfbox.cos.COSName;

import java.awt.geom.Point2D;
import java.io.File;
import java.util.*;

public class Probe {

    static class Seg {
        float x1, y1, x2, y2;
        Seg(float x1, float y1, float x2, float y2) { this.x1=x1; this.y1=y1; this.x2=x2; this.y2=y2; }
    }

    static class RulingCollector extends PDFGraphicsStreamEngine {
        final List<Seg> horizontal = new ArrayList<>();
        final List<Seg> vertical = new ArrayList<>();
        int imageCount = 0;
        private final List<float[]> pathPoints = new ArrayList<>();
        private float lastX, lastY;
        private final List<float[][]> subPaths = new ArrayList<>();
        private List<float[]> current = new ArrayList<>();

        RulingCollector(PDPage page) { super(page); }

        @Override public void appendRectangle(Point2D p0, Point2D p1, Point2D p2, Point2D p3) {
            // rectangle: add 4 edges
            addSeg((float)p0.getX(),(float)p0.getY(),(float)p1.getX(),(float)p1.getY());
            addSeg((float)p1.getX(),(float)p1.getY(),(float)p2.getX(),(float)p2.getY());
            addSeg((float)p2.getX(),(float)p2.getY(),(float)p3.getX(),(float)p3.getY());
            addSeg((float)p3.getX(),(float)p3.getY(),(float)p0.getX(),(float)p0.getY());
            pending.add(new Seg[0]); // marker not needed
        }
        List<Seg> segs = new ArrayList<>();
        List<Seg[]> pending = new ArrayList<>();
        void addSeg(float x1, float y1, float x2, float y2) {
            segs.add(new Seg(x1,y1,x2,y2));
        }
        @Override public void drawImage(PDImage pdImage) { imageCount++; }
        @Override public void clip(int windingRule) { }
        @Override public void moveTo(float x, float y) { lastX=x; lastY=y; }
        @Override public void lineTo(float x, float y) { addSeg(lastX,lastY,x,y); lastX=x; lastY=y; }
        @Override public void curveTo(float x1, float y1, float x2, float y2, float x3, float y3) { lastX=x3; lastY=y3; }
        @Override public Point2D getCurrentPoint() { return new Point2D.Float(lastX,lastY); }
        @Override public void closePath() { }
        @Override public void endPath() { segs.clear(); }
        @Override public void strokePath() { flush(); }
        @Override public void fillPath(int windingRule) { flush(); }
        @Override public void fillAndStrokePath(int windingRule) { flush(); }
        @Override public void shadingFill(COSName shadingName) { }

        void flush() {
            for (Seg s : segs) {
                float dx = Math.abs(s.x2 - s.x1);
                float dy = Math.abs(s.y2 - s.y1);
                if (dy <= 2.0f && dx >= 20f) horizontal.add(s);
                else if (dx <= 2.0f && dy >= 8f) vertical.add(s);
            }
            segs.clear();
        }
        void runPage() throws Exception { processPage(getPage()); }
    }

    static List<Float> cluster(List<Float> vals, float tol) {
        Collections.sort(vals);
        List<Float> out = new ArrayList<>();
        for (float v : vals) {
            if (out.isEmpty() || v - out.get(out.size()-1) > tol) out.add(v);
            else out.set(out.size()-1, (out.get(out.size()-1)+v)/2);
        }
        return out;
    }

    public static void main(String[] args) throws Exception {
        File root = new File(args[0]);
        List<File> pdfs = new ArrayList<>();
        for (File d : Objects.requireNonNull(root.listFiles())) {
            if (d.isDirectory()) for (File f : Objects.requireNonNull(d.listFiles()))
                if (f.getName().endsWith(".pdf")) pdfs.add(f);
        }
        Collections.sort(pdfs);
        for (File f : pdfs) {
            try (PDDocument doc = Loader.loadPDF(f)) {
                int n = doc.getNumberOfPages();
                int page = n > 1 ? 1 : 0; // second page usually pure table
                PDPage p = doc.getPage(page);
                RulingCollector rc = new RulingCollector(p);
                rc.runPage();
                // cluster distinct positions
                List<Float> hy = new ArrayList<>(); for (Seg s: rc.horizontal) hy.add((s.y1+s.y2)/2);
                List<Float> vx = new ArrayList<>(); for (Seg s: rc.vertical) vx.add((s.x1+s.x2)/2);
                List<Float> hC = cluster(hy, 3f);
                List<Float> vC = cluster(vx, 3f);
                // long verticals (span > 100pt)
                int longV = 0; for (Seg s : rc.vertical) if (Math.abs(s.y2-s.y1) > 100) longV++;
                int longH = 0; for (Seg s : rc.horizontal) if (Math.abs(s.x2-s.x1) > 200) longH++;
                String bank = f.getParentFile().getName();
                System.out.printf("%-28s %-12s pages=%-3d probePage=%d hLines=%-4d vLines=%-4d hPos=%-4d vPos=%-4d longV=%-4d longH=%-4d img=%d%n",
                        bank, f.getName(), n, page+1, rc.horizontal.size(), rc.vertical.size(), hC.size(), vC.size(), longV, longH, rc.imageCount);
            } catch (Exception e) {
                System.out.printf("%-28s %-12s ERROR %s%n", f.getParentFile().getName(), f.getName(), e.toString());
            }
        }
    }
}

