package com.finboost.bank.statement.parser.representation.document.extraction;

/**
 * Indicates which extraction engine produced the structured transaction rows
 * for a statement document.
 */
public enum ExtractionEngine {
    /**
     * The offline native transaction-table path produced the structured rows.
     */
    NATIVE,
    /**
     * The remote ML extraction path produced the structured rows.
     */
    ML,
    /**
     * A native policy was attempted for a supported layout but did not
     * succeed, so the result was produced by the remote ML path.
     */
    NATIVE_FALLBACK_ML
}

package com.finboost.bank.statement.parser.representation.document.extraction;

/**
 * Native transaction-table extraction policies. Each policy targets a family
 * of bank-statement layouts observed in the supported statement corpus.
 */
public enum NativeTableExtractionPolicy {
    /**
     * Fully ruled tables: horizontal and vertical ruling lines form a
     * complete cell lattice (e.g. AXIS, ICICI, SBI, PNB grid statements).
     */
    BORDERED_GRID,
    /**
     * Column boxes: long vertical ruling lines delimit the columns while rows
     * are derived from text baselines (e.g. HDFC, INDIAN column-box statements).
     */
    BOX_GUIDED,
    /**
     * No usable ruling lines: columns are recovered from whitespace alignment
     * and rows are selected by anchoring on date-leading lines
     * (e.g. KOTAK, CITI text statements).
     */
    TEXT_ALIGNED_ROW_SELECTED
}

