package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import lombok.AllArgsConstructor;
import lombok.Data;

/**
 * An axis-aligned ruling line extracted from the PDF vector content.
 * Coordinates are expressed in inches with the origin at the top-left corner
 * of the page (the same coordinate system used for {@code Word} polygons).
 */
@Data
@AllArgsConstructor
public class NativePdfRuling {

    public enum Orientation {
        HORIZONTAL,
        VERTICAL
    }

    private Orientation orientation;
    private float x1;
    private float y1;
    private float x2;
    private float y2;

    public float getLength() {
        return orientation == Orientation.HORIZONTAL ? Math.abs(x2 - x1) : Math.abs(y2 - y1);
    }

    /**
     * The fixed coordinate of the ruling: y for horizontal lines, x for vertical lines.
     */
    public float getPosition() {
        return orientation == Orientation.HORIZONTAL ? (y1 + y2) / 2f : (x1 + x2) / 2f;
    }

    public float getSpanStart() {
        return orientation == Orientation.HORIZONTAL ? Math.min(x1, x2) : Math.min(y1, y2);
    }

    public float getSpanEnd() {
        return orientation == Orientation.HORIZONTAL ? Math.max(x1, x2) : Math.max(y1, y2);
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.LinkedList;
import java.util.List;

/**
 * Geometry of a single PDF page extracted natively (offline): the words with
 * their polygons and the axis-aligned ruling lines. All coordinates are in
 * inches relative to the top-left corner of the page.
 */
@Data
@NoArgsConstructor
public class NativePdfPageGeometry {
    private int pageNumber;
    private double width;
    private double height;
    private List<Word> words = new LinkedList<>();
    private List<NativePdfRuling> horizontalRulings = new LinkedList<>();
    private List<NativePdfRuling> verticalRulings = new LinkedList<>();
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.extern.slf4j.Slf4j;
import org.apache.pdfbox.Loader;
import org.apache.pdfbox.contentstream.PDFGraphicsStreamEngine;
import org.apache.pdfbox.cos.COSName;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.graphics.image.PDImage;
import org.apache.pdfbox.text.PDFTextStripper;
import org.apache.pdfbox.text.TextPosition;
import org.springframework.stereotype.Service;

import java.awt.geom.Point2D;
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Extracts the native geometry (words with polygons plus axis-aligned ruling
 * lines) of an electronically generated PDF using PDFBox only. No remote
 * service is involved. All coordinates are converted to inches with the
 * origin at the top-left of the page so that the produced {@link Word}
 * objects use exactly the same coordinate conventions as the ML pipeline.
 */
@Service
@Slf4j
public class NativePdfGeometryExtractor {

    private static final float POINTS_PER_INCH = 72.0f;

    /** Minimum length (inches) of a segment to be considered a horizontal ruling. */
    private static final float MIN_HORIZONTAL_RULING_LENGTH = 0.25f;
    /** Minimum length (inches) of a segment to be considered a vertical ruling. */
    private static final float MIN_VERTICAL_RULING_LENGTH = 0.10f;
    /** Maximum thickness (inches) tolerated for an axis-aligned segment. */
    private static final float AXIS_ALIGNMENT_TOLERANCE = 0.03f;

    /**
     * Extracts geometry for all pages of the given PDF file.
     *
     * @return one geometry object per page, or an empty list when the PDF has
     *         no extractable text (e.g. scanned image statements)
     */
    public List<NativePdfPageGeometry> extractGeometry(File pdfFile) throws IOException {
        List<NativePdfPageGeometry> pages = new LinkedList<>();

        try (PDDocument document = Loader.loadPDF(pdfFile)) {
            int pageCount = document.getNumberOfPages();
            int totalCharacters = 0;

            for (int pageIndex = 0; pageIndex < pageCount; pageIndex++) {
                PDPage page = document.getPage(pageIndex);
                PDRectangle cropBox = page.getCropBox();

                NativePdfPageGeometry geometry = new NativePdfPageGeometry();
                geometry.setPageNumber(pageIndex + 1);
                geometry.setWidth(cropBox.getWidth() / POINTS_PER_INCH);
                geometry.setHeight(cropBox.getHeight() / POINTS_PER_INCH);

                // Characters -> words
                CharacterCollector collector = new CharacterCollector();
                collector.setStartPage(pageIndex + 1);
                collector.setEndPage(pageIndex + 1);
                collector.getText(document);
                totalCharacters += collector.characters.size();
                geometry.setWords(groupCharactersIntoWords(collector.characters, pageIndex + 1));

                // Vector graphics -> ruling lines
                try {
                    RulingCollector rulingCollector = new RulingCollector(page, cropBox);
                    rulingCollector.processPage(page);
                    geometry.setHorizontalRulings(rulingCollector.horizontalRulings);
                    geometry.setVerticalRulings(rulingCollector.verticalRulings);
                } catch (Exception e) {
                    log.warn("Failed to extract ruling lines from page {}: {}", pageIndex + 1, e.getMessage());
                }

                pages.add(geometry);
            }

            if (totalCharacters == 0) {
                log.info("No extractable characters found in PDF (likely scanned); native geometry unavailable");
                return new LinkedList<>();
            }
        }

        return pages;
    }

    // ------------------------------------------------------------------
    // Character extraction and word grouping
    // ------------------------------------------------------------------

    private static class NativeCharacter {
        final String text;
        final float x;        // left edge, inches
        final float baseline; // baseline (bottom), inches from top
        final float width;
        final float height;

        NativeCharacter(String text, float x, float baseline, float width, float height) {
            this.text = text;
            this.x = x;
            this.baseline = baseline;
            this.width = width;
            this.height = height;
        }
    }

    private static class CharacterCollector extends PDFTextStripper {
        final List<NativeCharacter> characters = new LinkedList<>();

        CharacterCollector() throws IOException {
            super();
            setSortByPosition(true);
        }

        @Override
        protected void processTextPosition(TextPosition text) {
            String unicode = text.getUnicode();
            if (unicode == null || unicode.trim().isEmpty()) {
                return;
            }
            float x = text.getXDirAdj() / POINTS_PER_INCH;
            float baseline = text.getYDirAdj() / POINTS_PER_INCH;
            float width = text.getWidthDirAdj() / POINTS_PER_INCH;
            float height = text.getHeightDir() / POINTS_PER_INCH;
            characters.add(new NativeCharacter(unicode, x, baseline, width, height));
        }
    }

    /**
     * Groups characters of a page into {@link Word} objects. Characters are
     * first clustered into text lines by baseline and then split into words
     * on horizontal whitespace gaps.
     */
    private List<Word> groupCharactersIntoWords(List<NativeCharacter> characters, int pageNumber) {
        List<Word> words = new LinkedList<>();
        if (characters.isEmpty()) {
            return words;
        }

        List<NativeCharacter> sorted = new ArrayList<>(characters);
        sorted.sort(Comparator.comparing((NativeCharacter c) -> c.baseline).thenComparing(c -> c.x));

        // Cluster into lines by baseline proximity
        List<List<NativeCharacter>> lines = new ArrayList<>();
        List<NativeCharacter> currentLine = null;
        float currentBaseline = 0f;
        for (NativeCharacter c : sorted) {
            float tolerance = Math.max(0.03f, c.height * 0.45f);
            if (currentLine == null || Math.abs(c.baseline - currentBaseline) > tolerance) {
                currentLine = new ArrayList<>();
                lines.add(currentLine);
                currentBaseline = c.baseline;
            }
            currentLine.add(c);
        }

        for (List<NativeCharacter> line : lines) {
            line.sort(Comparator.comparing(c -> c.x));

            float averageWidth = 0f;
            for (NativeCharacter c : line) {
                averageWidth += Math.max(c.width, 0.01f);
            }
            averageWidth = averageWidth / line.size();
            float gapThreshold = Math.max(0.035f, averageWidth * 0.60f);

            List<NativeCharacter> currentWord = new ArrayList<>();
            NativeCharacter previous = null;
            for (NativeCharacter c : line) {
                if (previous != null) {
                    float gap = c.x - (previous.x + previous.width);
                    if (gap > gapThreshold) {
                        addWord(words, currentWord, pageNumber);
                        currentWord = new ArrayList<>();
                    }
                }
                currentWord.add(c);
                previous = c;
            }
            addWord(words, currentWord, pageNumber);
        }

        return words;
    }

    private void addWord(List<Word> words, List<NativeCharacter> wordCharacters, int pageNumber) {
        if (wordCharacters == null || wordCharacters.isEmpty()) {
            return;
        }

        StringBuilder content = new StringBuilder();
        float minX = Float.MAX_VALUE;
        float maxX = -Float.MAX_VALUE;
        float minY = Float.MAX_VALUE;
        float maxY = -Float.MAX_VALUE;

        for (NativeCharacter c : wordCharacters) {
            content.append(c.text);
            minX = Math.min(minX, c.x);
            maxX = Math.max(maxX, c.x + Math.max(c.width, 0.005f));
            float top = c.baseline - Math.max(c.height, 0.02f);
            minY = Math.min(minY, top);
            maxY = Math.max(maxY, c.baseline);
        }

        String text = content.toString().trim();
        if (text.isEmpty()) {
            return;
        }

        Word word = new Word(text,
                minX, minY,   // top-left
                maxX, minY,   // top-right
                maxX, maxY,   // bottom-right
                minX, maxY,   // bottom-left
                pageNumber,
                maxX - minX,
                maxY - minY,
                pageNumber,
                0);
        words.add(word);
    }

    // ------------------------------------------------------------------
    // Ruling line extraction
    // ------------------------------------------------------------------

    private static class RulingCollector extends PDFGraphicsStreamEngine {
        final List<NativePdfRuling> horizontalRulings = new LinkedList<>();
        final List<NativePdfRuling> verticalRulings = new LinkedList<>();

        private final float pageTopY;
        private final float pageLeftX;
        private final List<float[]> pendingSegments = new LinkedList<>();
        private float lastX;
        private float lastY;

        RulingCollector(PDPage page, PDRectangle cropBox) {
            super(page);
            this.pageTopY = cropBox.getUpperRightY();
            this.pageLeftX = cropBox.getLowerLeftX();
        }

        private void addSegment(float x1, float y1, float x2, float y2) {
            pendingSegments.add(new float[]{x1, y1, x2, y2});
        }

        @Override
        public void appendRectangle(Point2D p0, Point2D p1, Point2D p2, Point2D p3) {
            addSegment((float) p0.getX(), (float) p0.getY(), (float) p1.getX(), (float) p1.getY());
            addSegment((float) p1.getX(), (float) p1.getY(), (float) p2.getX(), (float) p2.getY());
            addSegment((float) p2.getX(), (float) p2.getY(), (float) p3.getX(), (float) p3.getY());
            addSegment((float) p3.getX(), (float) p3.getY(), (float) p0.getX(), (float) p0.getY());
        }

        @Override
        public void drawImage(PDImage pdImage) {
            // ignored: rulings are vector graphics
        }

        @Override
        public void clip(int windingRule) {
            // ignored
        }

        @Override
        public void moveTo(float x, float y) {
            lastX = x;
            lastY = y;
        }

        @Override
        public void lineTo(float x, float y) {
            addSegment(lastX, lastY, x, y);
            lastX = x;
            lastY = y;
        }

        @Override
        public void curveTo(float x1, float y1, float x2, float y2, float x3, float y3) {
            // curves are not table rulings
            lastX = x3;
            lastY = y3;
        }

        @Override
        public Point2D getCurrentPoint() {
            return new Point2D.Float(lastX, lastY);
        }

        @Override
        public void closePath() {
            // ignored
        }

        @Override
        public void endPath() {
            pendingSegments.clear();
        }

        @Override
        public void strokePath() {
            flushSegments();
        }

        @Override
        public void fillPath(int windingRule) {
            flushSegments();
        }

        @Override
        public void fillAndStrokePath(int windingRule) {
            flushSegments();
        }

        @Override
        public void shadingFill(COSName shadingName) {
            // ignored
        }

        private void flushSegments() {
            for (float[] segment : pendingSegments) {
                float x1 = (segment[0] - pageLeftX) / POINTS_PER_INCH;
                float y1 = (pageTopY - segment[1]) / POINTS_PER_INCH;
                float x2 = (segment[2] - pageLeftX) / POINTS_PER_INCH;
                float y2 = (pageTopY - segment[3]) / POINTS_PER_INCH;

                float dx = Math.abs(x2 - x1);
                float dy = Math.abs(y2 - y1);

                if (dy <= AXIS_ALIGNMENT_TOLERANCE && dx >= MIN_HORIZONTAL_RULING_LENGTH) {
                    float y = (y1 + y2) / 2f;
                    horizontalRulings.add(new NativePdfRuling(NativePdfRuling.Orientation.HORIZONTAL,
                            Math.min(x1, x2), y, Math.max(x1, x2), y));
                } else if (dx <= AXIS_ALIGNMENT_TOLERANCE && dy >= MIN_VERTICAL_RULING_LENGTH) {
                    float x = (x1 + x2) / 2f;
                    verticalRulings.add(new NativePdfRuling(NativePdfRuling.Orientation.VERTICAL,
                            x, Math.min(y1, y2), x, Math.max(y1, y2)));
                }
            }
            pendingSegments.clear();
        }
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TableCell;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * Shared geometry helpers used by the native transaction-table builders.
 * All coordinates are in inches, origin top-left.
 */
public final class NativeTableGeometryUtil {

    private NativeTableGeometryUtil() {
    }

    /** Date token patterns used to anchor transaction rows. */
    private static final Pattern[] DATE_PATTERNS = new Pattern[]{
            Pattern.compile("^\\d{1,2}[-/.]\\d{1,2}[-/.]\\d{2,4}$"),
            Pattern.compile("^\\d{1,2}[-/. ]?[A-Za-z]{3,9}[-/. ]?\\d{2,4}$"),
            Pattern.compile("^\\d{4}[-/.]\\d{1,2}[-/.]\\d{1,2}$"),
            Pattern.compile("^\\d{1,2}[-/.]\\d{1,2}[-/.]\\d{2,4}\\d{0,2}:?\\d{0,2}$")
    };

    private static final String[] HEADER_KEYWORDS = new String[]{
            "date", "particular", "description", "narration", "details", "remark",
            "chq", "cheque", "ref", "withdrawal", "deposit", "debit", "credit",
            "amount", "balance", "txn", "transaction", "value", "instrument"
    };

    /** A cluster of words sharing (approximately) the same baseline. */
    public static class TextRow {
        public final List<Word> words = new ArrayList<>();
        public float top = Float.MAX_VALUE;
        public float bottom = -Float.MAX_VALUE;
        public float left = Float.MAX_VALUE;
        public float right = -Float.MAX_VALUE;

        void add(Word word) {
            words.add(word);
            top = Math.min(top, Math.min(word.getY1(), word.getY2()));
            bottom = Math.max(bottom, Math.max(word.getY3(), word.getY4()));
            left = Math.min(left, Math.min(word.getX1(), word.getX4()));
            right = Math.max(right, Math.max(word.getX2(), word.getX3()));
        }

        public float centerY() {
            return (top + bottom) / 2f;
        }

        public String getText() {
            StringBuilder builder = new StringBuilder();
            words.stream()
                    .sorted(Comparator.comparing(Word::getX1))
                    .forEach(word -> {
                        if (builder.length() > 0) {
                            builder.append(' ');
                        }
                        builder.append(word.getContent());
                    });
            return builder.toString();
        }
    }

    /** A horizontal band of the page that constitutes a single table row. */
    public static class RowBand {
        public final float top;
        public final float bottom;

        public RowBand(float top, float bottom) {
            this.top = top;
            this.bottom = bottom;
        }
    }

    /**
     * Clusters the given words into text rows ordered from top to bottom.
     */
    public static List<TextRow> buildTextRows(List<Word> words) {
        List<TextRow> rows = new LinkedList<>();
        if (words == null || words.isEmpty()) {
            return rows;
        }

        List<Word> sorted = new ArrayList<>(words);
        sorted.sort(Comparator.comparing((Word w) -> (w.getY1() + w.getY4()) / 2f).thenComparing(Word::getX1));

        TextRow current = null;
        for (Word word : sorted) {
            float centerY = (word.getY1() + word.getY4()) / 2f;
            float tolerance = Math.max(0.035f, word.getHeight() != null ? word.getHeight() * 0.55f : 0.035f);
            if (current == null || Math.abs(centerY - current.centerY()) > tolerance) {
                current = new TextRow();
                rows.add(current);
            }
            current.add(word);
        }

        rows.sort(Comparator.comparing(TextRow::centerY));
        return rows;
    }

    /**
     * Returns whether the token looks like a transaction-date value.
     */
    public static boolean isDateToken(String token) {
        if (token == null) {
            return false;
        }
        String value = token.trim();
        if (value.length() < 5 || value.length() > 22) {
            return false;
        }
        for (Pattern pattern : DATE_PATTERNS) {
            if (pattern.matcher(value).matches()) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts how many transaction-table header keywords appear in the row text.
     */
    public static int countHeaderKeywords(String rowText) {
        if (rowText == null || rowText.isEmpty()) {
            return 0;
        }
        String lower = rowText.toLowerCase(Locale.ROOT);
        int count = 0;
        for (String keyword : HEADER_KEYWORDS) {
            if (lower.contains(keyword)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Returns whether the row looks like a transaction-table header row
     * (contains a date keyword together with other table headings).
     */
    public static boolean isHeaderRow(TextRow row) {
        String text = row.getText().toLowerCase(Locale.ROOT);
        return text.contains("date") && countHeaderKeywords(text) >= 3;
    }

    /**
     * Returns whether a text row is anchored on a date token, i.e. its first
     * (left-most) word is a date value. Rows of a transaction table start
     * with the transaction date in all supported layouts.
     */
    public static boolean isDateAnchoredRow(TextRow row) {
        if (row.words.isEmpty()) {
            return false;
        }
        List<Word> ordered = new ArrayList<>(row.words);
        ordered.sort(Comparator.comparing(Word::getX1));
        String first = ordered.get(0).getContent();
        if (isDateToken(first)) {
            return true;
        }
        // date split across two words, e.g. "01 Jan 2024" / "01-01" "2024"
        if (ordered.size() >= 2) {
            String joined = first + ordered.get(1).getContent();
            if (isDateToken(joined)) {
                return true;
            }
            if (ordered.size() >= 3) {
                String joined3 = joined + ordered.get(2).getContent();
                return isDateToken(joined3);
            }
        }
        return false;
    }

    /**
     * Builds row bands by anchoring on date-leading text rows. Header rows
     * (rows above the first anchor) become one band each. Continuation rows
     * following an anchor row are merged into the anchor row's band.
     *
     * @param rows              text rows inside the table region, top to bottom
     * @param maxContinuation   max continuation lines merged into an anchor row
     * @return ordered row bands, or an empty list when no anchor row exists
     */
    public static List<RowBand> buildDateAnchoredRowBands(List<TextRow> rows, int maxContinuation) {
        List<RowBand> bands = new LinkedList<>();
        int firstAnchor = -1;
        for (int i = 0; i < rows.size(); i++) {
            if (isDateAnchoredRow(rows.get(i))) {
                firstAnchor = i;
                break;
            }
        }
        if (firstAnchor < 0) {
            return bands;
        }

        // header / leading rows: one band per text row
        for (int i = 0; i < firstAnchor; i++) {
            TextRow row = rows.get(i);
            bands.add(new RowBand(row.top - 0.01f, row.bottom + 0.01f));
        }

        int i = firstAnchor;
        while (i < rows.size()) {
            TextRow anchor = rows.get(i);
            if (!isDateAnchoredRow(anchor)) {
                i++;
                continue;
            }
            float top = anchor.top - 0.01f;
            float bottom = anchor.bottom + 0.01f;
            int continuation = 0;
            int j = i + 1;
            while (j < rows.size() && !isDateAnchoredRow(rows.get(j)) && continuation < maxContinuation) {
                TextRow next = rows.get(j);
                float gap = next.top - bottom;
                if (gap > 0.30f) {
                    break;
                }
                bottom = Math.max(bottom, next.bottom + 0.01f);
                continuation++;
                j++;
            }
            bands.add(new RowBand(top, bottom));
            i = j;
        }

        return bands;
    }

    /**
     * Derives column boundaries from whitespace alignment: unions the words'
     * horizontal intervals over the given rows and places a boundary in the
     * middle of every persistent gap.
     *
     * @param rows        text rows to accumulate occupancy from
     * @param minGapWidth minimum width (inches) of a whitespace gap that
     *                    separates two columns
     * @return sorted column boundaries including the outer left/right edges
     */
    public static List<Float> deriveColumnBoundariesFromAlignment(List<TextRow> rows, float minGapWidth) {
        List<float[]> intervals = new ArrayList<>();
        for (TextRow row : rows) {
            for (Word word : row.words) {
                float left = Math.min(word.getX1(), word.getX4());
                float right = Math.max(word.getX2(), word.getX3());
                intervals.add(new float[]{left, right});
            }
        }
        if (intervals.isEmpty()) {
            return new ArrayList<>();
        }

        intervals.sort(Comparator.comparing(interval -> interval[0]));

        // merge intervals that touch or nearly touch
        List<float[]> merged = new ArrayList<>();
        float[] current = intervals.get(0).clone();
        for (int i = 1; i < intervals.size(); i++) {
            float[] interval = intervals.get(i);
            if (interval[0] - current[1] < minGapWidth) {
                current[1] = Math.max(current[1], interval[1]);
            } else {
                merged.add(current);
                current = interval.clone();
            }
        }
        merged.add(current);

        List<Float> boundaries = new ArrayList<>();
        boundaries.add(merged.get(0)[0] - 0.05f);
        for (int i = 0; i < merged.size() - 1; i++) {
            boundaries.add((merged.get(i)[1] + merged.get(i + 1)[0]) / 2f);
        }
        boundaries.add(merged.get(merged.size() - 1)[1] + 0.05f);
        return boundaries;
    }

    /**
     * Clusters ruling positions (x for vertical, y for horizontal rulings)
     * into distinct boundary values.
     */
    public static List<List<NativePdfRuling>> clusterRulingsByPosition(List<NativePdfRuling> rulings, float tolerance) {
        List<List<NativePdfRuling>> clusters = new ArrayList<>();
        if (rulings == null || rulings.isEmpty()) {
            return clusters;
        }
        List<NativePdfRuling> sorted = new ArrayList<>(rulings);
        sorted.sort(Comparator.comparing(NativePdfRuling::getPosition));

        List<NativePdfRuling> current = null;
        float clusterStart = 0f;
        for (NativePdfRuling ruling : sorted) {
            if (current == null || ruling.getPosition() - clusterStart > tolerance) {
                current = new ArrayList<>();
                clusters.add(current);
                clusterStart = ruling.getPosition();
            }
            current.add(ruling);
        }
        return clusters;
    }

    public static float clusterPosition(List<NativePdfRuling> cluster) {
        float sum = 0f;
        for (NativePdfRuling ruling : cluster) {
            sum += ruling.getPosition();
        }
        return sum / cluster.size();
    }

    public static float clusterSpanStart(List<NativePdfRuling> cluster) {
        float min = Float.MAX_VALUE;
        for (NativePdfRuling ruling : cluster) {
            min = Math.min(min, ruling.getSpanStart());
        }
        return min;
    }

    public static float clusterSpanEnd(List<NativePdfRuling> cluster) {
        float max = -Float.MAX_VALUE;
        for (NativePdfRuling ruling : cluster) {
            max = Math.max(max, ruling.getSpanEnd());
        }
        return max;
    }

    /**
     * Total length of the cluster's rulings that overlaps [from, to].
     */
    public static float clusterCoverage(List<NativePdfRuling> cluster, float from, float to) {
        float coverage = 0f;
        for (NativePdfRuling ruling : cluster) {
            float start = Math.max(ruling.getSpanStart(), from);
            float end = Math.min(ruling.getSpanEnd(), to);
            if (end > start) {
                coverage += (end - start);
            }
        }
        return coverage;
    }

    /**
     * Assembles a {@link Table} from column boundaries and row bands,
     * assigning every word whose centre falls inside a cell.
     */
    public static Table buildTable(int pageNumber, List<Float> columnBoundaries, List<RowBand> rowBands, List<Word> pageWords) {
        if (columnBoundaries == null || columnBoundaries.size() < 2 || rowBands == null || rowBands.isEmpty()) {
            return null;
        }

        List<Float> boundaries = new ArrayList<>(columnBoundaries);
        boundaries.sort(Comparator.naturalOrder());

        float tableLeft = boundaries.get(0);
        float tableRight = boundaries.get(boundaries.size() - 1);
        float tableTop = rowBands.get(0).top;
        float tableBottom = rowBands.get(rowBands.size() - 1).bottom;

        int totalColumns = boundaries.size() - 1;
        Map<Integer, Map<Integer, TableCell>> cells = new LinkedHashMap<>();

        for (int rowIndex = 0; rowIndex < rowBands.size(); rowIndex++) {
            RowBand band = rowBands.get(rowIndex);
            Map<Integer, TableCell> row = new LinkedHashMap<>();
            for (int colIndex = 0; colIndex < totalColumns; colIndex++) {
                TableCell cell = new TableCell();
                cell.setRowindex(rowIndex);
                cell.setColindex(colIndex);
                cell.setRowspan(1);
                cell.setColspan(1);
                float left = boundaries.get(colIndex);
                float right = boundaries.get(colIndex + 1);
                cell.setX1(left);
                cell.setY1(band.top);
                cell.setX2(right);
                cell.setY2(band.top);
                cell.setX3(right);
                cell.setY3(band.bottom);
                cell.setX4(left);
                cell.setY4(band.bottom);
                cell.setWords(new LinkedList<>());
                row.put(colIndex, cell);
            }
            cells.put(rowIndex, row);
        }

        // assign words to cells by centre point
        int assignedWords = 0;
        for (Word word : pageWords) {
            float centerX = (word.getX1() + word.getX2() + word.getX3() + word.getX4()) / 4f;
            float centerY = (word.getY1() + word.getY2() + word.getY3() + word.getY4()) / 4f;
            if (centerX < tableLeft || centerX > tableRight || centerY < tableTop || centerY > tableBottom) {
                continue;
            }

            int colIndex = -1;
            for (int c = 0; c < totalColumns; c++) {
                if (centerX >= boundaries.get(c) && centerX <= boundaries.get(c + 1)) {
                    colIndex = c;
                    break;
                }
            }
            if (colIndex < 0) {
                continue;
            }

            int rowIndex = -1;
            for (int r = 0; r < rowBands.size(); r++) {
                if (centerY >= rowBands.get(r).top && centerY <= rowBands.get(r).bottom) {
                    rowIndex = r;
                    break;
                }
            }
            if (rowIndex < 0) {
                continue;
            }

            cells.get(rowIndex).get(colIndex).getWords().add(word);
            assignedWords++;
        }

        if (assignedWords == 0) {
            return null;
        }

        Table table = new Table();
        table.setPageNumber(pageNumber);
        table.setX1(tableLeft);
        table.setY1(tableTop);
        table.setX2(tableRight);
        table.setY2(tableTop);
        table.setX3(tableRight);
        table.setY3(tableBottom);
        table.setX4(tableLeft);
        table.setY4(tableBottom);
        table.setTotalRows(rowBands.size());
        table.setTotalColumns(totalColumns);
        table.setSpanOffset(0);
        table.setSpanLength(0);
        table.setCells(cells);
        table.setColType(new ArrayList<>());
        table.setTxnColType(new ArrayList<>());
        table.setColumnBoundaries(boundaries);
        return table;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableExtractionPolicy;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;

import java.util.List;

/**
 * Builds candidate transaction tables from the native geometry of a single
 * PDF page according to one layout policy.
 */
public interface NativeTransactionTableBuilder {

    NativeTableExtractionPolicy getPolicy();

    /**
     * @return the tables detected on the page (possibly empty, never null)
     */
    List<Table> buildTables(NativePdfPageGeometry page);
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableExtractionPolicy;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

import static com.finboost.bank.statement.parser.service.document.extraction.nativepdf.NativeTableGeometryUtil.*;

/**
 * Native table builder for fully ruled ("bordered grid") statement layouts:
 * horizontal and vertical ruling lines form a complete cell lattice. Row
 * bands are taken from consecutive horizontal rulings and column intervals
 * from the vertical rulings covering the table region.
 */
@Component
@Slf4j
public class BorderedGridTableBuilder implements NativeTransactionTableBuilder {

    private static final float POSITION_TOLERANCE = 0.03f;
    private static final float MIN_HORIZONTAL_SPAN = 1.0f;
    private static final float MAX_ROW_GAP = 1.5f;
    private static final int MIN_ROW_BOUNDARIES = 3;
    private static final int MIN_COLUMN_BOUNDARIES = 4;
    private static final float MIN_ROW_HEIGHT = 0.05f;
    private static final float MIN_VERTICAL_COVERAGE_RATIO = 0.35f;

    @Override
    public NativeTableExtractionPolicy getPolicy() {
        return NativeTableExtractionPolicy.BORDERED_GRID;
    }

    @Override
    public List<Table> buildTables(NativePdfPageGeometry page) {
        List<Table> tables = new LinkedList<>();

        // distinct horizontal boundary positions with a substantial span
        List<List<NativePdfRuling>> horizontalClusters = clusterRulingsByPosition(page.getHorizontalRulings(), POSITION_TOLERANCE);
        List<HorizontalBoundary> boundaries = new ArrayList<>();
        for (List<NativePdfRuling> cluster : horizontalClusters) {
            float spanStart = clusterSpanStart(cluster);
            float spanEnd = clusterSpanEnd(cluster);
            if (spanEnd - spanStart >= MIN_HORIZONTAL_SPAN) {
                boundaries.add(new HorizontalBoundary(clusterPosition(cluster), spanStart, spanEnd));
            }
        }
        boundaries.sort(Comparator.comparing(boundary -> boundary.y));

        // group consecutive horizontal boundaries into candidate tables
        List<List<HorizontalBoundary>> groups = new ArrayList<>();
        List<HorizontalBoundary> currentGroup = null;
        for (HorizontalBoundary boundary : boundaries) {
            if (currentGroup == null) {
                currentGroup = startGroup(groups, boundary);
                continue;
            }
            HorizontalBoundary previous = currentGroup.get(currentGroup.size() - 1);
            boolean sameTable = boundary.y - previous.y <= MAX_ROW_GAP
                    && horizontalOverlapRatio(previous, boundary) >= 0.5f;
            if (sameTable) {
                currentGroup.add(boundary);
            } else {
                currentGroup = startGroup(groups, boundary);
            }
        }

        List<List<NativePdfRuling>> verticalClusters = clusterRulingsByPosition(page.getVerticalRulings(), POSITION_TOLERANCE);

        for (List<HorizontalBoundary> group : groups) {
            if (group.size() < MIN_ROW_BOUNDARIES) {
                continue;
            }

            float tableTop = group.get(0).y;
            float tableBottom = group.get(group.size() - 1).y;
            float tableHeight = tableBottom - tableTop;
            if (tableHeight <= MIN_ROW_HEIGHT) {
                continue;
            }

            // vertical boundaries: clusters with sufficient coverage of the table height
            List<Float> columnBoundaries = new ArrayList<>();
            for (List<NativePdfRuling> cluster : verticalClusters) {
                float coverage = clusterCoverage(cluster, tableTop, tableBottom);
                if (coverage >= tableHeight * MIN_VERTICAL_COVERAGE_RATIO) {
                    columnBoundaries.add(clusterPosition(cluster));
                }
            }
            if (columnBoundaries.size() < MIN_COLUMN_BOUNDARIES) {
                continue;
            }

            // row bands from consecutive horizontal boundaries
            List<RowBand> rowBands = new ArrayList<>();
            for (int i = 0; i < group.size() - 1; i++) {
                float top = group.get(i).y;
                float bottom = group.get(i + 1).y;
                if (bottom - top >= MIN_ROW_HEIGHT) {
                    rowBands.add(new RowBand(top, bottom));
                }
            }
            if (rowBands.isEmpty()) {
                continue;
            }

            Table table = buildTable(page.getPageNumber(), columnBoundaries, rowBands, page.getWords());
            if (table != null) {
                tables.add(table);
            }
        }

        return tables;
    }

    private static List<HorizontalBoundary> startGroup(List<List<HorizontalBoundary>> groups, HorizontalBoundary boundary) {
        List<HorizontalBoundary> group = new ArrayList<>();
        group.add(boundary);
        groups.add(group);
        return group;
    }

    private static float horizontalOverlapRatio(HorizontalBoundary a, HorizontalBoundary b) {
        float overlap = Math.min(a.spanEnd, b.spanEnd) - Math.max(a.spanStart, b.spanStart);
        float shorter = Math.min(a.spanEnd - a.spanStart, b.spanEnd - b.spanStart);
        if (shorter <= 0f) {
            return 0f;
        }
        return Math.max(0f, overlap) / shorter;
    }

    private static class HorizontalBoundary {
        final float y;
        final float spanStart;
        final float spanEnd;

        HorizontalBoundary(float y, float spanStart, float spanEnd) {
            this.y = y;
            this.spanStart = spanStart;
            this.spanEnd = spanEnd;
        }
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableExtractionPolicy;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

import static com.finboost.bank.statement.parser.service.document.extraction.nativepdf.NativeTableGeometryUtil.*;

/**
 * Native table builder for "box guided" statement layouts: long vertical
 * ruling lines delimit the table columns while horizontal separators are
 * sparse or absent. Rows are derived from text baselines and anchored on
 * date-leading lines so that multi-line descriptions collapse into their
 * transaction row.
 */
@Component
@Slf4j
public class BoxGuidedTableBuilder implements NativeTransactionTableBuilder {

    private static final float POSITION_TOLERANCE = 0.03f;
    private static final float MIN_COLUMN_RULING_LENGTH = 0.5f;
    private static final int MIN_COLUMN_BOUNDARIES = 4;
    private static final int MAX_CONTINUATION_LINES = 8;

    @Override
    public NativeTableExtractionPolicy getPolicy() {
        return NativeTableExtractionPolicy.BOX_GUIDED;
    }

    @Override
    public List<Table> buildTables(NativePdfPageGeometry page) {
        List<Table> tables = new LinkedList<>();

        // keep vertical rulings long enough to be column separators
        List<NativePdfRuling> columnRulings = new ArrayList<>();
        for (NativePdfRuling ruling : page.getVerticalRulings()) {
            if (ruling.getLength() >= MIN_COLUMN_RULING_LENGTH) {
                columnRulings.add(ruling);
            }
        }

        List<List<NativePdfRuling>> clusters = clusterRulingsByPosition(columnRulings, POSITION_TOLERANCE);
        if (clusters.size() < MIN_COLUMN_BOUNDARIES) {
            return tables;
        }

        // group column boundaries into boxes with mutually overlapping vertical extents
        List<ColumnBoundary> columnBoundaries = new ArrayList<>();
        for (List<NativePdfRuling> cluster : clusters) {
            columnBoundaries.add(new ColumnBoundary(clusterPosition(cluster),
                    clusterSpanStart(cluster), clusterSpanEnd(cluster)));
        }
        columnBoundaries.sort(Comparator.comparing(boundary -> boundary.x));

        List<List<ColumnBoundary>> boxes = new ArrayList<>();
        for (ColumnBoundary boundary : columnBoundaries) {
            List<ColumnBoundary> target = null;
            for (List<ColumnBoundary> box : boxes) {
                if (verticalOverlapRatio(box, boundary) >= 0.5f) {
                    target = box;
                    break;
                }
            }
            if (target == null) {
                target = new ArrayList<>();
                boxes.add(target);
            }
            target.add(boundary);
        }

        for (List<ColumnBoundary> box : boxes) {
            if (box.size() < MIN_COLUMN_BOUNDARIES) {
                continue;
            }

            float top = Float.MAX_VALUE;
            float bottom = -Float.MAX_VALUE;
            float left = Float.MAX_VALUE;
            float right = -Float.MAX_VALUE;
            List<Float> boundaries = new ArrayList<>();
            for (ColumnBoundary boundary : box) {
                boundaries.add(boundary.x);
                top = Math.min(top, boundary.top);
                bottom = Math.max(bottom, boundary.bottom);
                left = Math.min(left, boundary.x);
                right = Math.max(right, boundary.x);
            }

            // rows from text lines inside the box region
            List<Word> regionWords = new ArrayList<>();
            for (Word word : page.getWords()) {
                float centerX = (word.getX1() + word.getX2() + word.getX3() + word.getX4()) / 4f;
                float centerY = (word.getY1() + word.getY2() + word.getY3() + word.getY4()) / 4f;
                if (centerX >= left && centerX <= right && centerY >= top - 0.02f && centerY <= bottom + 0.02f) {
                    regionWords.add(word);
                }
            }
            if (regionWords.isEmpty()) {
                continue;
            }

            List<TextRow> textRows = buildTextRows(regionWords);
            List<RowBand> rowBands = buildDateAnchoredRowBands(textRows, MAX_CONTINUATION_LINES);
            if (rowBands.isEmpty()) {
                // no date anchor found inside the box (e.g. header-only box):
                // fall back to one band per text row so continuation pages
                // without any date row are still skipped naturally
                continue;
            }

            Table table = buildTable(page.getPageNumber(), boundaries, rowBands, page.getWords());
            if (table != null) {
                tables.add(table);
            }
        }

        return tables;
    }

    private static float verticalOverlapRatio(List<ColumnBoundary> box, ColumnBoundary boundary) {
        float boxTop = Float.MAX_VALUE;
        float boxBottom = -Float.MAX_VALUE;
        for (ColumnBoundary member : box) {
            boxTop = Math.min(boxTop, member.top);
            boxBottom = Math.max(boxBottom, member.bottom);
        }
        float overlap = Math.min(boxBottom, boundary.bottom) - Math.max(boxTop, boundary.top);
        float shorter = Math.min(boxBottom - boxTop, boundary.bottom - boundary.top);
        if (shorter <= 0f) {
            return 0f;
        }
        return Math.max(0f, overlap) / shorter;
    }

    private static class ColumnBoundary {
        final float x;
        final float top;
        final float bottom;

        ColumnBoundary(float x, float top, float bottom) {
            this.x = x;
            this.top = top;
            this.bottom = bottom;
        }
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableExtractionPolicy;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

import static com.finboost.bank.statement.parser.service.document.extraction.nativepdf.NativeTableGeometryUtil.*;

/**
 * Native table builder for text-only statement layouts without usable ruling
 * lines. Transaction rows are selected by anchoring on date-leading text
 * lines ("row selected") and the column intervals are recovered from the
 * whitespace alignment of the selected rows ("text aligned").
 */
@Component
@Slf4j
public class TextAlignedRowSelectedTableBuilder implements NativeTransactionTableBuilder {

    private static final int MIN_COLUMNS = 4;
    private static final int MAX_CONTINUATION_LINES = 8;
    private static final float MIN_COLUMN_GAP = 0.10f;
    /** Minimum anchored rows required when no header line is present. */
    private static final int MIN_ANCHORS_WITHOUT_HEADER = 4;

    @Override
    public NativeTableExtractionPolicy getPolicy() {
        return NativeTableExtractionPolicy.TEXT_ALIGNED_ROW_SELECTED;
    }

    @Override
    public List<Table> buildTables(NativePdfPageGeometry page) {
        List<Table> tables = new LinkedList<>();

        List<TextRow> allRows = buildTextRows(page.getWords());
        if (allRows.isEmpty()) {
            return tables;
        }

        // locate the transaction-table header line, if any
        int headerIndex = -1;
        for (int i = 0; i < allRows.size(); i++) {
            if (isHeaderRow(allRows.get(i))) {
                headerIndex = i;
                break;
            }
        }

        // candidate region: from the header line (when found) downwards,
        // otherwise the whole page (continuation pages carry no header)
        List<TextRow> candidateRows = new ArrayList<>();
        for (int i = Math.max(headerIndex, 0); i < allRows.size(); i++) {
            candidateRows.add(allRows.get(i));
        }

        // anchored transaction rows drive both row selection and column alignment
        List<TextRow> anchorRows = new ArrayList<>();
        for (TextRow row : candidateRows) {
            if (isDateAnchoredRow(row)) {
                anchorRows.add(row);
            }
        }
        if (anchorRows.isEmpty()) {
            return tables;
        }
        if (headerIndex < 0 && anchorRows.size() < MIN_ANCHORS_WITHOUT_HEADER) {
            return tables;
        }

        // column boundaries from whitespace alignment of the anchored rows
        // (headers are excluded: their labels often bridge column gaps)
        List<Float> columnBoundaries = deriveColumnBoundariesFromAlignment(anchorRows, MIN_COLUMN_GAP);
        if (columnBoundaries.size() - 1 < MIN_COLUMNS) {
            return tables;
        }

        // restrict the candidate rows to the ones between the first anchor
        // (or the header) and the last anchor plus its continuation lines
        List<TextRow> tableRows = new ArrayList<>();
        int firstAnchorIndex = candidateRows.indexOf(anchorRows.get(0));
        int lastAnchorIndex = candidateRows.indexOf(anchorRows.get(anchorRows.size() - 1));
        int start = headerIndex >= 0 ? 0 : firstAnchorIndex;
        int end = Math.min(candidateRows.size() - 1, lastAnchorIndex + MAX_CONTINUATION_LINES);
        for (int i = start; i <= end; i++) {
            tableRows.add(candidateRows.get(i));
        }

        List<RowBand> rowBands = buildDateAnchoredRowBands(tableRows, MAX_CONTINUATION_LINES);
        if (rowBands.isEmpty()) {
            return tables;
        }

        Table table = buildTable(page.getPageNumber(), columnBoundaries, rowBands, page.getWords());
        if (table != null) {
            tables.add(table);
        }
        return tables;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableExtractionPolicy;
import org.springframework.stereotype.Component;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

import static com.finboost.bank.statement.parser.representation.document.extraction.NativeTableExtractionPolicy.*;

/**
 * Maps supported bank-format families to their native transaction-table
 * extraction policies. The assignments are derived from the layout analysis
 * of the repository's statement fixture corpus
 * ({@code src/test/resources/pdf-samples-latest}):
 *
 * <ul>
 *   <li><b>BORDERED_GRID</b> - full ruled lattices (AXIS, ICICI, SBI, PNB,
 *       UNION, FEDERAL, DEUSTCHE, IDFC, INDIAN OVERSEAS, YES, RBL, AHMEDNAGAR,
 *       BANDHAN, TJSB, GS Mahanagar, Standard Chartered, Suryoday,
 *       IndusInd);</li>
 *   <li><b>BOX_GUIDED</b> - long vertical column separators with sparse
 *       horizontal rules (HDFC, INDIAN, CBI, IDBI);</li>
 *   <li><b>TEXT_ALIGNED_ROW_SELECTED</b> - no usable column rulings
 *       (KOTAK, CITI, BOB row-separator layouts).</li>
 * </ul>
 *
 * Secondary policies cover minority formats inside a family (e.g. AXIS
 * format3 is a text-only layout). Banks not listed here are unsupported by
 * the native path and are routed to the remote ML extraction by default.
 */
@Component
public class NativeTableExtractionPolicyRegistry {

    private final Map<String, List<NativeTableExtractionPolicy>> policiesByBank = new HashMap<>();

    public NativeTableExtractionPolicyRegistry() {
        // Bordered-grid families
        register("AXIS", BORDERED_GRID, TEXT_ALIGNED_ROW_SELECTED);
        register("ICICI", BORDERED_GRID, TEXT_ALIGNED_ROW_SELECTED);
        register("SBI", BORDERED_GRID, TEXT_ALIGNED_ROW_SELECTED);
        register("PNB", BORDERED_GRID, TEXT_ALIGNED_ROW_SELECTED);
        register("UNION", BORDERED_GRID, TEXT_ALIGNED_ROW_SELECTED);
        register("FEDERAL", BORDERED_GRID);
        register("DEUSTCHE", BORDERED_GRID);
        register("DEUTSCHE", BORDERED_GRID);
        register("IDFC", BORDERED_GRID);
        register("INDIAN_OVERSEAS", BORDERED_GRID);
        register("YES", BORDERED_GRID);
        register("RBL", BORDERED_GRID, TEXT_ALIGNED_ROW_SELECTED);
        register("AHMEDNAGAR", BORDERED_GRID);
        register("BANDHAN", BORDERED_GRID);
        register("TJSB", BORDERED_GRID);
        register("TJSB_BANK", BORDERED_GRID);
        register("GS_MAHANAGAR_CO_OP_BANK", BORDERED_GRID);
        register("STANDARD_CHARTERED", BORDERED_GRID);
        register("SURYODAY_SMALL_FINANCE_BANK_LTD", BORDERED_GRID);
        register("INDUSIND", BORDERED_GRID, BOX_GUIDED);

        // Box-guided families (long vertical column separators)
        register("HDFC", BOX_GUIDED, BORDERED_GRID);
        register("INDIAN", BOX_GUIDED);
        register("CBI", BOX_GUIDED, TEXT_ALIGNED_ROW_SELECTED);
        register("IDBI", BOX_GUIDED);

        // Text-aligned families (no usable column rulings)
        register("KOTAK", TEXT_ALIGNED_ROW_SELECTED);
        register("CITI", TEXT_ALIGNED_ROW_SELECTED);
        register("BOB", TEXT_ALIGNED_ROW_SELECTED, BORDERED_GRID);
    }

    private void register(String bankCode, NativeTableExtractionPolicy... policies) {
        policiesByBank.put(bankCode, Arrays.asList(policies));
    }

    /**
     * Resolves the ordered native policy candidates for a bank-format family.
     *
     * @return the candidate policies, or an empty list when the family is not
     *         supported by the native path (remote ML remains the default)
     */
    public List<NativeTableExtractionPolicy> resolvePolicies(String bankCode) {
        if (bankCode == null || bankCode.trim().isEmpty()) {
            return Collections.emptyList();
        }
        String normalized = bankCode.trim().toUpperCase(Locale.ROOT).replace(' ', '_');
        return policiesByBank.getOrDefault(normalized, Collections.emptyList());
    }

    public boolean isSupported(String bankCode) {
        return !resolvePolicies(bankCode).isEmpty();
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.bankAccount.BankTransactionVO;
import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableExtractionPolicy;
import com.finboost.bank.statement.parser.representation.document.extraction.Page;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TableCell;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.bankstatement.InconsistencyFinderService;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.AnalyzeDocuments;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;

/**
 * Offline native transaction-table extraction. Produces a
 * {@link DocumentExtractionResult} that is structurally identical to the one
 * produced by the remote ML path, so the existing downstream document
 * analysis (column typing, header/footer identification, transaction-table
 * identification and row normalization) runs unchanged on top of it.
 *
 * The result of a policy is only accepted when the downstream analysis
 * identifies a transaction table whose extracted rows form a consistent
 * balance sequence; otherwise the caller falls back to the remote ML path.
 */
@Service
@Slf4j
public class NativeTransactionTableExtractionService {

    private NativePdfGeometryExtractor geometryExtractor;
    private AnalyzeDocuments analyzeDocuments;
    private List<NativeTransactionTableBuilder> tableBuilders;

    @Autowired
    public void setGeometryExtractor(NativePdfGeometryExtractor geometryExtractor) {
        this.geometryExtractor = geometryExtractor;
    }

    @Autowired
    public void setAnalyzeDocuments(AnalyzeDocuments analyzeDocuments) {
        this.analyzeDocuments = analyzeDocuments;
    }

    @Autowired
    public void setTableBuilders(List<NativeTransactionTableBuilder> tableBuilders) {
        this.tableBuilders = tableBuilders;
    }

    /**
     * Attempts native extraction of the statement using the given ordered
     * policy candidates.
     *
     * @return a fully analyzed extraction result when a policy succeeds and
     *         passes validation, otherwise {@code null}
     */
    public DocumentExtractionResult extract(File statementFile, List<NativeTableExtractionPolicy> policies) throws IOException {
        if (statementFile == null || policies == null || policies.isEmpty()) {
            return null;
        }

        List<NativePdfPageGeometry> geometry = geometryExtractor.extractGeometry(statementFile);
        if (geometry == null || geometry.isEmpty()) {
            log.info("Native geometry unavailable for {}; deferring to remote ML extraction", statementFile.getName());
            return null;
        }

        for (NativeTableExtractionPolicy policy : policies) {
            NativeTransactionTableBuilder builder = findBuilder(policy);
            if (builder == null) {
                continue;
            }
            try {
                DocumentExtractionResult result = buildResult(geometry, builder);
                if (result == null) {
                    continue;
                }

                runDownstreamAnalysis(result);

                if (isValidTransactionResult(result)) {
                    result.setNativeExtractionPolicy(policy);
                    log.info("Native transaction-table extraction succeeded with policy {} for {}",
                            policy, statementFile.getName());
                    return result;
                }
                log.info("Native policy {} did not produce a consistent transaction table for {}",
                        policy, statementFile.getName());
            } catch (Exception e) {
                log.warn("Native policy {} failed for {}: {}", policy, statementFile.getName(), e.getMessage());
            }
        }

        return null;
    }

    private NativeTransactionTableBuilder findBuilder(NativeTableExtractionPolicy policy) {
        if (tableBuilders == null) {
            return null;
        }
        for (NativeTransactionTableBuilder builder : tableBuilders) {
            if (builder.getPolicy() == policy) {
                return builder;
            }
        }
        return null;
    }

    private DocumentExtractionResult buildResult(List<NativePdfPageGeometry> geometry, NativeTransactionTableBuilder builder) {
        Map<Integer, Page> pages = new HashMap<>();
        int tableCount = 0;

        for (NativePdfPageGeometry pageGeometry : geometry) {
            Page page = new Page();
            page.setPageNumber(pageGeometry.getPageNumber());
            page.setWidth(pageGeometry.getWidth());
            page.setHeight(pageGeometry.getHeight());
            page.setWords(new ArrayList<>(pageGeometry.getWords()));
            page.setContent(buildPageContent(pageGeometry.getWords()));

            Map<Integer, Table> tables = new LinkedHashMap<>();
            int tableIndex = 0;
            for (Table table : builder.buildTables(pageGeometry)) {
                tables.put(tableIndex++, table);
                tableCount++;
            }
            page.setTables(tables);

            pages.put(pageGeometry.getPageNumber(), page);
        }

        if (tableCount == 0) {
            return null;
        }

        DocumentExtractionResult result = new DocumentExtractionResult();
        result.setPages(pages);
        result.setNoOfPages(geometry.size());
        assignWordIndices(result);
        return result;
    }

    private String buildPageContent(List<Word> words) {
        StringBuilder content = new StringBuilder();
        for (NativeTableGeometryUtil.TextRow row : NativeTableGeometryUtil.buildTextRows(words)) {
            if (content.length() > 0) {
                content.append('\n');
            }
            content.append(row.getText());
        }
        return content.toString();
    }

    /**
     * Assigns page/word indices to the words referenced by table cells, using
     * the same ordering conventions as the ML response mapper.
     */
    private void assignWordIndices(DocumentExtractionResult result) {
        int currentWordIndex = 1;

        List<Integer> pageNumbers = new ArrayList<>(result.getPages().keySet());
        Collections.sort(pageNumbers);

        for (Integer pageNumber : pageNumbers) {
            Page page = result.getPages().get(pageNumber);
            if (page.getTables() == null) {
                continue;
            }
            List<Integer> tableIndices = new ArrayList<>(page.getTables().keySet());
            Collections.sort(tableIndices);
            for (Integer tableIndex : tableIndices) {
                Table table = page.getTables().get(tableIndex);
                if (table.getCells() == null) {
                    continue;
                }
                List<Integer> rowIndices = new ArrayList<>(table.getCells().keySet());
                Collections.sort(rowIndices);
                for (Integer rowIndex : rowIndices) {
                    Map<Integer, TableCell> row = table.getCells().get(rowIndex);
                    if (row == null) {
                        continue;
                    }
                    List<Integer> cellIndices = new ArrayList<>(row.keySet());
                    Collections.sort(cellIndices);
                    for (Integer cellIndex : cellIndices) {
                        TableCell cell = row.get(cellIndex);
                        if (cell.getWords() == null) {
                            continue;
                        }
                        for (Word word : cell.getWords()) {
                            word.setPageIndex(pageNumber);
                            word.setWordIndex(currentWordIndex++);
                        }
                    }
                }
            }
        }
    }

    /**
     * Runs the same downstream document analysis that the ML path applies
     * after mapping the remote response.
     */
    private void runDownstreamAnalysis(DocumentExtractionResult result) {
        DocumentExtractionResult preProcessedByHeader = analyzeDocuments.preProcessForVerificationByHeader(result, 5);
        if (preProcessedByHeader != null && preProcessedByHeader.getPreProcessVerificationResult() != null) {
            result.setPreProcessVerificationResult(preProcessedByHeader.getPreProcessVerificationResult());
        } else {
            DocumentExtractionResult preProcessed = analyzeDocuments.preProcessForVerification(result, result.getNoOfPages());
            if (preProcessed != null && preProcessed.getPreProcessVerificationResult() != null) {
                result.setPreProcessVerificationResult(preProcessed.getPreProcessVerificationResult());
            }
        }
        analyzeDocuments.analyzeDocument(result, true, true, true);
    }

    /**
     * Validation gate for the native path: the analyzed result must contain a
     * transaction table whose extracted rows parse into transactions with a
     * consistent balance sequence (in statement order or reverse order).
     */
    private boolean isValidTransactionResult(DocumentExtractionResult result) {
        boolean hasTransactionTable = false;
        for (Page page : result.getPages().values()) {
            if (page.getTables() == null) {
                continue;
            }
            for (Table table : page.getTables().values()) {
                if (table.getIsTransactionTable()) {
                    hasTransactionTable = true;
                    break;
                }
            }
        }
        if (!hasTransactionTable) {
            return false;
        }

        BankStatementVO probeStatement = new BankStatementVO();
        probeStatement.setDocumentExtractionResult(result);
        List<BankStatementVO> probeList = new LinkedList<>();
        probeList.add(probeStatement);
        try {
            BankStatementProcessorImpl.extractTransactions(probeList, false);
        } catch (Exception e) {
            log.warn("Native validation failed while extracting transactions: {}", e.getMessage());
            return false;
        }

        List<BankTransactionVO> transactions = probeStatement.getBankTransactions();
        if (transactions == null || transactions.isEmpty()) {
            return false;
        }

        Integer inconsistencyCount = InconsistencyFinderService.checkInconsistencyForCount(transactions);
        if (inconsistencyCount != null && inconsistencyCount == 0) {
            return true;
        }

        List<BankTransactionVO> reversed = new LinkedList<>();
        for (int i = transactions.size() - 1; i >= 0; i--) {
            reversed.add(transactions.get(i));
        }
        Integer reversedInconsistencyCount = InconsistencyFinderService.checkInconsistencyForCount(reversed);
        return reversedInconsistencyCount != null && reversedInconsistencyCount == 0;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction;

import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.ExtractionEngine;
import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableExtractionPolicy;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.NativeTableExtractionPolicyRegistry;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.NativeTransactionTableExtractionService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.util.List;

/**
 * Document extraction entry point that prefers the offline native
 * transaction-table path for supported bank-format families and falls back
 * to the remote ML path otherwise.
 *
 * <ul>
 *   <li>Supported native layout succeeds: the native result is carried
 *       through downstream document analysis and the remote ML extraction is
 *       never invoked ({@link ExtractionEngine#NATIVE}).</li>
 *   <li>Supported native layout fails validation: the remote ML path is used
 *       ({@link ExtractionEngine#NATIVE_FALLBACK_ML}).</li>
 *   <li>Unknown or unsupported layout: the remote ML path remains the
 *       default ({@link ExtractionEngine#ML}).</li>
 * </ul>
 */
@Service("hybridDocumentExtractionServiceImpl")
@Slf4j
public class HybridDocumentExtractionServiceImpl implements DocumentExtractionService {

    private DocumentExtractionService mlDocumentExtractionService;
    private NativeTransactionTableExtractionService nativeTransactionTableExtractionService;
    private NativeTableExtractionPolicyRegistry nativeTableExtractionPolicyRegistry;

    @Autowired
    @Qualifier("azureDocumentExtractionServiceImpl")
    public void setMlDocumentExtractionService(DocumentExtractionService mlDocumentExtractionService) {
        this.mlDocumentExtractionService = mlDocumentExtractionService;
    }

    @Autowired
    public void setNativeTransactionTableExtractionService(NativeTransactionTableExtractionService nativeTransactionTableExtractionService) {
        this.nativeTransactionTableExtractionService = nativeTransactionTableExtractionService;
    }

    @Autowired
    public void setNativeTableExtractionPolicyRegistry(NativeTableExtractionPolicyRegistry nativeTableExtractionPolicyRegistry) {
        this.nativeTableExtractionPolicyRegistry = nativeTableExtractionPolicyRegistry;
    }

    @Override
    public DocumentExtractionResult extractDocument(BankStatementVO bankStatementVO) throws IOException {
        DocumentExtractionRequest documentExtractionRequest = new DocumentExtractionRequest();
        documentExtractionRequest.setStatementFile(bankStatementVO.getDecryptedFile());
        documentExtractionRequest.setBankName(bankStatementVO.getBank());
        try {
            documentExtractionRequest.setStatementFromDate(BankStatementProcessorImpl.parseDate(bankStatementVO.getBankAccountDetailsVO().getStatementFrom()));
        } catch (Exception e) {
            log.warn("Failed to parse statement-from-date from date string {}", bankStatementVO.getBankAccountDetailsVO().getStatementFrom());
        }
        return extractDocument(documentExtractionRequest);
    }

    @Override
    public DocumentExtractionResult extractDocument(DocumentExtractionRequest request) throws IOException {
        boolean nativeAttempted = false;

        List<NativeTableExtractionPolicy> policies = nativeTableExtractionPolicyRegistry.resolvePolicies(request.getBankName());
        if (!policies.isEmpty()) {
            nativeAttempted = true;
            try {
                DocumentExtractionResult nativeResult =
                        nativeTransactionTableExtractionService.extract(request.getStatementFile(), policies);
                if (nativeResult != null) {
                    nativeResult.setExtractionEngine(ExtractionEngine.NATIVE);
                    log.info("Statement processed by native extraction (policy {}), remote ML not invoked",
                            nativeResult.getNativeExtractionPolicy());
                    return nativeResult;
                }
            } catch (Exception e) {
                log.warn("Native extraction failed for bank {}; falling back to remote ML: {}",
                        request.getBankName(), e.getMessage());
            }
        }

        DocumentExtractionResult mlResult = mlDocumentExtractionService.extractDocument(request);
        if (mlResult != null) {
            mlResult.setExtractionEngine(nativeAttempted ? ExtractionEngine.NATIVE_FALLBACK_ML : ExtractionEngine.ML);
        }
        return mlResult;
    }
}

