/**
 * Builds per-statement extraction diagnostics (native / ML / native-to-ML
 * fallback) for the API response.
 */
private static List<StatementExtractionDiagnosticsDTO> buildStatementDiagnostics(List<BankStatementVO> bankStatementVOList) {
    List<StatementExtractionDiagnosticsDTO> diagnostics = new ArrayList<>();
    if (bankStatementVOList == null) {
        return diagnostics;
    }
    for (BankStatementVO bankStatementVO : bankStatementVOList) {
        StatementExtractionDiagnosticsDTO dto = new StatementExtractionDiagnosticsDTO();
        dto.setFileId(bankStatementVO.getFileId());
        dto.setFileName(bankStatementVO.getOriginalFileName());
        dto.setBank(bankStatementVO.getBank());
        dto.setExtractionEngine(bankStatementVO.getExtractionEngineName());
        dto.setNativeExtractionPolicy(bankStatementVO.getNativeExtractionPolicyName());
        diagnostics.add(dto);
    }
    return diagnostics;
}

/**
 * Aggregates the extraction engine over the statements of an account:
 * a single common engine name, or MIXED when statements were produced by
 * different engines.
 */
private static String aggregateExtractionEngine(List<BankStatementVO> statements) {
    if (statements == null || statements.isEmpty()) {
        return null;
    }
    Set<String> engines = statements.stream()
            .map(BankStatementVO::getExtractionEngineName)
            .filter(Objects::nonNull)
            .collect(Collectors.toSet());
    if (engines.isEmpty()) {
        return null;
    }
    if (engines.size() == 1) {
        return engines.iterator().next();
    }
    return "MIXED";
}

