import com.finboost.bank.statement.parser.representation.document.extraction.*;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.*;

import java.io.File;
import java.util.*;

public class SmokeNative {
    public static void main(String[] args) throws Exception {
        NativePdfGeometryExtractor extractor = new NativePdfGeometryExtractor();
        List<NativeTransactionTableBuilder> builders = List.of(
                new BorderedGridTableBuilder(),
                new BoxGuidedTableBuilder(),
                new TextAlignedRowSelectedTableBuilder());

        String[][] samples = {
                {"/app/src/test/resources/pdf-samples-latest/AXIS/format1.pdf", "BORDERED_GRID"},
                {"/app/src/test/resources/pdf-samples-latest/ICICI/format1.pdf", "BORDERED_GRID"},
                {"/app/src/test/resources/pdf-samples-latest/SBI/format1.pdf", "BORDERED_GRID"},
                {"/app/src/test/resources/pdf-samples-latest/HDFC/format5.pdf", "BOX_GUIDED"},
                {"/app/src/test/resources/pdf-samples-latest/INDIAN/format1.pdf", "BOX_GUIDED"},
                {"/app/src/test/resources/pdf-samples-latest/KOTAK/format1.pdf", "TEXT_ALIGNED_ROW_SELECTED"},
                {"/app/src/test/resources/pdf-samples-latest/BOB/format1.pdf", "TEXT_ALIGNED_ROW_SELECTED"},
        };

        for (String[] sample : samples) {
            File f = new File(sample[0]);
            NativeTableExtractionPolicy policy = NativeTableExtractionPolicy.valueOf(sample[1]);
            NativeTransactionTableBuilder builder = builders.stream().filter(b -> b.getPolicy() == policy).findFirst().get();
            try {
                List<NativePdfPageGeometry> geo = extractor.extractGeometry(f);
                if (geo.isEmpty()) { System.out.println(f.getName() + " -> no geometry"); continue; }
                NativePdfPageGeometry pg = geo.size() > 1 ? geo.get(1) : geo.get(0);
                List<Table> tables = builder.buildTables(pg);
                System.out.println("=== " + sample[0].replace("/app/src/test/resources/pdf-samples-latest/","") + " policy=" + policy + " page=" + pg.getPageNumber()
                        + " words=" + pg.getWords().size() + " hRul=" + pg.getHorizontalRulings().size() + " vRul=" + pg.getVerticalRulings().size()
                        + " tables=" + tables.size());
                for (Table t : tables) {
                    System.out.println("  table rows=" + t.getTotalRows() + " cols=" + t.getTotalColumns());
                    int shown = 0;
                    for (Map.Entry<Integer, Map<Integer, TableCell>> row : t.getCells().entrySet()) {
                        if (shown++ >= 4) break;
                        StringBuilder sb = new StringBuilder("   row" + row.getKey() + ": ");
                        for (Map.Entry<Integer, TableCell> c : row.getValue().entrySet()) {
                            String content = c.getValue().getContent();
                            if (content.length() > 28) content = content.substring(0, 28) + "..";
                            sb.append("[").append(content).append("] ");
                        }
                        System.out.println(sb);
                    }
                }
            } catch (Exception e) {
                System.out.println(f.getName() + " ERROR: " + e);
                e.printStackTrace();
            }
        }
    }
}

