public class Debug2 {
    public static void main(String[] args) throws Exception {
        NativePdfGeometryExtractor extractor = new NativePdfGeometryExtractor();
        for (String path : args) {
            File f = new File(path);
            List<NativePdfPageGeometry> geo = extractor.extractGeometry(f);
            if (geo.isEmpty()) { System.out.println(path + " no geometry"); continue; }
            NativePdfPageGeometry pg = geo.size() > 1 ? geo.get(1) : geo.get(0);
            System.out.println("=== " + path + " page " + pg.getPageNumber());
            // vertical clusters
            List<NativePdfRuling> longV = new ArrayList<>();
            for (NativePdfRuling r : pg.getVerticalRulings()) if (r.getLength() >= 0.5f) longV.add(r);
            List<List<NativePdfRuling>> clusters = NativeTableGeometryUtil.clusterRulingsByPosition(longV, 0.03f);
            for (List<NativePdfRuling> c : clusters) {
                System.out.printf("  vCluster x=%.2f top=%.2f bottom=%.2f n=%d%n",
                        NativeTableGeometryUtil.clusterPosition(c),
                        NativeTableGeometryUtil.clusterSpanStart(c),
                        NativeTableGeometryUtil.clusterSpanEnd(c), c.size());
            }
            // text rows and date-anchor status (first 25 rows)
            List<NativeTableGeometryUtil.TextRow> rows = NativeTableGeometryUtil.buildTextRows(pg.getWords());
            int shown = 0;
            for (NativeTableGeometryUtil.TextRow row : rows) {
                if (shown++ >= 30) break;
                String t = row.getText();
                if (t.length() > 100) t = t.substring(0, 100);
                System.out.printf("  row y=%.2f anchor=%b hdr=%b: %s%n", row.centerY(),
                        NativeTableGeometryUtil.isDateAnchoredRow(row), NativeTableGeometryUtil.isHeaderRow(row), t);
            }
        }
    }
}

