/**
 * Derives column boundaries from whitespace alignment using occupancy
 * voting: the horizontal extent is sampled in small bins and a column
 * boundary is placed in the middle of every gap that is whitespace in
 * (nearly) all of the given rows. Voting makes the detection robust
 * against isolated stray rows (e.g. footer timestamps) that would
 * otherwise bridge a column gap.
 *
 * @param rows        text rows to accumulate occupancy from
 * @param minGapWidth minimum width (inches) of a whitespace gap that
 *                    separates two columns
 * @return sorted column boundaries including the outer left/right edges
 */
public static List<Float> deriveColumnBoundariesFromAlignment(List<TextRow> rows, float minGapWidth) {
    List<Float> boundaries = new ArrayList<>();
    if (rows == null || rows.isEmpty()) {
        return boundaries;
    }

    float left = Float.MAX_VALUE;
    float right = -Float.MAX_VALUE;
    for (TextRow row : rows) {
        left = Math.min(left, row.left);
        right = Math.max(right, row.right);
    }
    if (right - left < minGapWidth) {
        return boundaries;
    }

    final float binWidth = 0.02f;
    int binCount = (int) Math.ceil((right - left) / binWidth);
    int[] occupancy = new int[binCount];

    for (TextRow row : rows) {
        for (Word word : row.words) {
            float wordLeft = Math.min(word.getX1(), word.getX4());
            float wordRight = Math.max(word.getX2(), word.getX3());
            int from = Math.max(0, (int) ((wordLeft - left) / binWidth));
            int to = Math.min(binCount - 1, (int) ((wordRight - left) / binWidth));
            for (int bin = from; bin <= to; bin++) {
                occupancy[bin]++;
            }
        }
    }

    // a bin is "whitespace" when only a negligible fraction of rows covers it
    int maxGapOccupancy = Math.max(1, (int) Math.ceil(rows.size() * 0.06f)) - 1;
    int minGapBins = Math.max(1, Math.round(minGapWidth / binWidth));

    boundaries.add(left - 0.05f);
    int gapStart = -1;
    for (int bin = 0; bin <= binCount; bin++) {
        boolean whitespace = bin < binCount && occupancy[bin] <= maxGapOccupancy;
        if (whitespace) {
            if (gapStart < 0) {
                gapStart = bin;
            }
        } else if (gapStart >= 0) {
            int gapBins = bin - gapStart;
            // ignore leading gaps (before the first occupied bin)
            if (gapStart > 0 && gapBins >= minGapBins) {
                float gapCenter = left + (gapStart + gapBins / 2f) * binWidth;
                boundaries.add(gapCenter);
            }
            gapStart = -1;
        }
    }
    boundaries.add(right + 0.05f);
    return boundaries;
}

