/** Amount-like token, e.g. "4,848.00", "(236.00)", "51,852.00Cr". */
private static final Pattern AMOUNT_PATTERN =
        Pattern.compile("^-?\\(?[0-9][0-9,]*\\.\\d{1,2}\\)?(Cr|Dr|CR|DR|cr|dr)?\\.?$");

/**
 * Returns whether the row contains at least one amount-like token.
 */
public static boolean hasAmountToken(TextRow row) {
    for (Word word : row.words) {
        String content = word.getContent();
        if (content != null && AMOUNT_PATTERN.matcher(content.trim()).matches()) {
            return true;
        }
    }
    return false;
}

/**
 * Builds row bands by anchoring on date-leading text rows. Header rows
 * (rows above the first anchor) become one band each and continuation
 * rows are merged into their anchor row's band.
 *
 * The merge direction is inferred from the data: normally the amount and
 * balance live on the anchor row itself and wrapped description lines
 * follow it (forward merging). Some layouts (e.g. KOTAK) print the
 * amounts on the line above the serial/date line, in which case the
 * preceding lines are merged instead (backward merging).
 *
 * @param rows              text rows inside the table region, top to bottom
 * @param maxContinuation   max continuation lines merged into an anchor row
 * @return ordered row bands, or an empty list when no anchor row exists
 */
public static List<RowBand> buildDateAnchoredRowBands(List<TextRow> rows, int maxContinuation) {
    List<RowBand> bands = new LinkedList<>();
    List<Integer> anchorIndices = new ArrayList<>();
    for (int i = 0; i < rows.size(); i++) {
        if (isDateAnchoredRow(rows.get(i))) {
            anchorIndices.add(i);
        }
    }
    if (anchorIndices.isEmpty()) {
        return bands;
    }

    int anchorsWithAmount = 0;
    for (Integer anchorIndex : anchorIndices) {
        if (hasAmountToken(rows.get(anchorIndex))) {
            anchorsWithAmount++;
        }
    }
    boolean backwardMerging = anchorsWithAmount * 2 < anchorIndices.size();

    return backwardMerging
            ? buildBackwardMergedBands(rows, anchorIndices, maxContinuation)
            : buildForwardMergedBands(rows, anchorIndices.get(0), maxContinuation);
}

private static List<RowBand> buildForwardMergedBands(List<TextRow> rows, int firstAnchor, int maxContinuation) {
    List<RowBand> bands = new LinkedList<>();

    // header / leading rows: one band per text row
    for (int i = 0; i < firstAnchor; i++) {
        TextRow row = rows.get(i);
        bands.add(new RowBand(row.top - 0.01f, row.bottom + 0.01f));
    }

    int i = firstAnchor;
    while (i < rows.size()) {
        TextRow anchor = rows.get(i);
        if (!isDateAnchoredRow(anchor)) {
            i++;
            continue;
        }
        float top = anchor.top - 0.01f;
        float bottom = anchor.bottom + 0.01f;
        int continuation = 0;
        int j = i + 1;
        while (j < rows.size() && !isDateAnchoredRow(rows.get(j)) && !isHeaderRow(rows.get(j))
                && continuation < maxContinuation) {
            TextRow next = rows.get(j);
            float gap = next.top - bottom;
            if (gap > 0.30f) {
                break;
            }
            bottom = Math.max(bottom, next.bottom + 0.01f);
            continuation++;
            j++;
        }
        bands.add(new RowBand(top, bottom));
        i = j;
    }

    return bands;
}

private static List<RowBand> buildBackwardMergedBands(List<TextRow> rows, List<Integer> anchorIndices, int maxContinuation) {
    List<RowBand> bands = new LinkedList<>();
    boolean[] consumed = new boolean[rows.size()];

    List<RowBand> anchorBands = new ArrayList<>();
    int previousAnchor = -1;
    for (Integer anchorIndex : anchorIndices) {
        TextRow anchor = rows.get(anchorIndex);
        float top = anchor.top - 0.01f;
        float bottom = anchor.bottom + 0.01f;
        consumed[anchorIndex] = true;

        int continuation = 0;
        int j = anchorIndex - 1;
        while (j > previousAnchor && j >= 0 && !consumed[j] && continuation < maxContinuation) {
            TextRow candidate = rows.get(j);
            if (isDateAnchoredRow(candidate) || isHeaderRow(candidate)) {
                break;
            }
            float gap = top - candidate.bottom;
            if (gap > 0.30f) {
                break;
            }
            top = Math.min(top, candidate.top - 0.01f);
            consumed[j] = true;
            continuation++;
            j--;
        }
        anchorBands.add(new RowBand(top, bottom));
        previousAnchor = anchorIndex;
    }

    // unconsumed rows before the first anchor band become leading bands
    int firstAnchorIndex = anchorIndices.get(0);
    for (int i = 0; i < firstAnchorIndex; i++) {
        if (!consumed[i]) {
            TextRow row = rows.get(i);
            bands.add(new RowBand(row.top - 0.01f, row.bottom + 0.01f));
        }
    }
    bands.addAll(anchorBands);
    return bands;
}

