import com.finboost.bank.statement.parser.representation.document.extraction.*;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.beans.factory.support.BeanDefinitionRegistry;
import org.springframework.beans.factory.support.RootBeanDefinition;
import org.springframework.context.annotation.ClassPathBeanDefinitionScanner;

import java.io.File;
import java.util.*;

public class EndToEnd {
    public static void main(String[] args) throws Exception {
        AnnotationConfigApplicationContext ctx = new AnnotationConfigApplicationContext();
        ClassPathBeanDefinitionScanner scanner = new ClassPathBeanDefinitionScanner((BeanDefinitionRegistry) ctx.getBeanFactory());
        scanner.scan(
                "com.finboost.bank.statement.parser.service.document.extraction.post.processor",
                "com.finboost.bank.statement.parser.service.document.extraction.bankstatement.bank",
                "com.finboost.bank.statement.parser.service.document.extraction.nativepdf");
        // remove beans requiring remote services
        ((BeanDefinitionRegistry) ctx.getBeanFactory()).removeBeanDefinition("statementBasicDetailExtractor");
        ctx.registerBeanDefinition("statementBasicDetailExtractor",
                new RootBeanDefinition(com.finboost.bank.statement.parser.service.document.extraction.post.processor.StatementBasicDetailExtractor.class));
        ctx.registerBeanDefinition("bankSpecificParsingServiceImpl",
                new RootBeanDefinition(com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankSpecificParsingServiceImpl.class));
        try {
            ctx.refresh();
        } catch (Exception e) {
            System.out.println("Context failure: " + e.getMessage());
            return;
        }

        NativeTransactionTableExtractionService nativeService = ctx.getBean(NativeTransactionTableExtractionService.class);
        NativeTableExtractionPolicyRegistry registry = ctx.getBean(NativeTableExtractionPolicyRegistry.class);

        File root = new File("/app/src/test/resources/pdf-samples-latest");
        List<File> pdfs = new ArrayList<>();
        for (File d : Objects.requireNonNull(root.listFiles()))
            if (d.isDirectory()) for (File f : Objects.requireNonNull(d.listFiles()))
                if (f.getName().endsWith(".pdf")) pdfs.add(f);
        Collections.sort(pdfs);

        int nativeOk = 0, fallback = 0, unsupported = 0;
        for (File f : pdfs) {
            String bank = f.getParentFile().getName();
            List<NativeTableExtractionPolicy> policies = registry.resolvePolicies(bank);
            String label = bank + "/" + f.getName();
            if (policies.isEmpty()) { System.out.printf("%-40s UNSUPPORTED -> ML%n", label); unsupported++; continue; }
            long start = System.currentTimeMillis();
            try {
                DocumentExtractionResult result = nativeService.extract(f, policies);
                long ms = System.currentTimeMillis() - start;
                if (result != null) {
                    System.out.printf("%-40s NATIVE (%s) %dms%n", label, result.getNativeExtractionPolicy(), ms);
                    nativeOk++;
                } else {
                    System.out.printf("%-40s FALLBACK-ML %dms%n", label, ms);
                    fallback++;
                }
            } catch (Throwable t) {
                System.out.printf("%-40s ERROR %s%n", label, t);
                fallback++;
            }
        }
        System.out.printf("%nSummary: native=%d fallback=%d unsupported=%d total=%d%n", nativeOk, fallback, unsupported, pdfs.size());
    }
}

