import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.finboost.bank.statement.parser.representation.bankAccount.BankTransactionVO;
import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.*;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.*;
import org.springframework.beans.factory.support.BeanDefinitionRegistry;
import org.springframework.beans.factory.support.RootBeanDefinition;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.context.annotation.ClassPathBeanDefinitionScanner;

import java.io.File;
import java.math.BigDecimal;
import java.text.SimpleDateFormat;
import java.util.*;

public class Verify {
    public static void main(String[] args) throws Exception {
        AnnotationConfigApplicationContext ctx = new AnnotationConfigApplicationContext();
        ClassPathBeanDefinitionScanner scanner = new ClassPathBeanDefinitionScanner((BeanDefinitionRegistry) ctx.getBeanFactory());
        scanner.scan(
                "com.finboost.bank.statement.parser.service.document.extraction.post.processor",
                "com.finboost.bank.statement.parser.service.document.extraction.bankstatement.bank",
                "com.finboost.bank.statement.parser.service.document.extraction.nativepdf");
        ctx.getBeanFactory().registerSingleton("azureOpenAiCommunicationService",
                new com.finboost.bank.statement.parser.service.generative.ai.azure.gpt.AzureOpenAiCommunicationService());
        ctx.registerBeanDefinition("bankSpecificParsingServiceImpl",
                new RootBeanDefinition(com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankSpecificParsingServiceImpl.class));
        ctx.refresh();

        NativeTransactionTableExtractionService nativeService = ctx.getBean(NativeTransactionTableExtractionService.class);
        NativeTableExtractionPolicyRegistry registry = ctx.getBean(NativeTableExtractionPolicyRegistry.class);

        ObjectMapper mapper = new ObjectMapper();
        JsonNode cfg = mapper.readTree(new File("/app/src/test/resources/pdf-test-config-latest.json"));
        SimpleDateFormat sdf = new SimpleDateFormat("dd/MM/yyyy");

        int filesNative = 0, filesFallback = 0, txOk = 0, txBad = 0;
        List<String> problems = new ArrayList<>();
        for (JsonNode tc : cfg.get("testCases")) {
            String rel = tc.get("pdfPath").asText().replace("classpath:", "");
            File pdf = new File("/app/src/test/resources/" + rel);
            String bank = pdf.getParentFile().getName();
            List<NativeTableExtractionPolicy> policies = registry.resolvePolicies(bank);
            if (policies.isEmpty()) continue;
            DocumentExtractionResult result;
            try {
                result = nativeService.extract(pdf, policies);
            } catch (Exception e) { result = null; }
            if (result == null) { filesFallback++; continue; }
            filesNative++;

            BankStatementVO vo = new BankStatementVO();
            vo.setDocumentExtractionResult(result);
            List<BankStatementVO> list = new LinkedList<>();
            list.add(vo);
            BankStatementProcessorImpl.extractTransactions(list, true);
            List<BankTransactionVO> txns = vo.getBankTransactions();

            for (JsonNode et : tc.get("expectedTransactions")) {
                int idx = et.get("index").asInt();
                String reason = null;
                if (txns == null || idx >= txns.size()) {
                    reason = "missing index " + idx + " (size=" + (txns == null ? 0 : txns.size()) + ")";
                } else {
                    BankTransactionVO t = txns.get(idx);
                    String expDate = et.get("transactionDate").asText();
                    double expAmount = et.get("amount").asDouble();
                    double expBalance = et.get("balance").asDouble();
                    String expType = et.get("type").asText();
                    if (!sdf.format(t.getTransactionDate()).equals(expDate)) reason = "date " + sdf.format(t.getTransactionDate()) + "!=" + expDate;
                    else if (t.getTransactionAmount().subtract(BigDecimal.valueOf(expAmount)).abs().doubleValue() > 0.01) reason = "amount " + t.getTransactionAmount() + "!=" + expAmount;
                    else if (t.getTransactionBalance().subtract(BigDecimal.valueOf(expBalance)).abs().doubleValue() > 0.01) reason = "balance " + t.getTransactionBalance() + "!=" + expBalance;
                    else if (!t.getTransactionType().name().equals(expType)) reason = "type " + t.getTransactionType() + "!=" + expType;
                }
                if (reason == null) txOk++;
                else { txBad++; problems.add(rel + " idx" + idx + ": " + reason); }
            }
        }
        System.out.println("filesNative=" + filesNative + " filesFallback=" + filesFallback + " txOk=" + txOk + " txBad=" + txBad);
        problems.forEach(p -> System.out.println("  " + p));
    }
}

