package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableExtractionPolicy;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;
import java.util.TreeSet;

import static com.finboost.bank.statement.parser.service.document.extraction.nativepdf.NativeTableGeometryUtil.*;

/**
 * Native table builder for "box guided" statement layouts: vertical ruling
 * lines (either continuous lines or stacks of per-row segments at the same x
 * position) delimit the table columns while horizontal separators are sparse
 * or absent. Rows are derived from text baselines and anchored on
 * date-leading lines so that multi-line descriptions collapse into their
 * transaction row.
 *
 * Column boundaries are grouped into boxes by the similarity of their
 * vertical extents (boundaries of one table share the same top/bottom), and
 * each box is then extended with the outer border lines that fully cover its
 * region. This keeps tables apart from account-information panels and
 * summary boxes that share the same page.
 */
@Component
@Slf4j
public class BoxGuidedTableBuilder implements NativeTransactionTableBuilder {

    private static final float POSITION_TOLERANCE = 0.03f;
    /** Minimum vertical extent (inches) of a column-boundary stack. */
    private static final float MIN_BOUNDARY_EXTENT = 0.4f;
    /** Minimum fraction of the extent that the stack's segments must cover. */
    private static final float MIN_STACK_COVERAGE_RATIO = 0.55f;
    /** Tolerance (inches) when matching boundary extents into one box. */
    private static final float EXTENT_GROUP_TOLERANCE = 0.35f;
    /** Fraction of the box height an extending boundary must cover. */
    private static final float MIN_EXTENSION_COVERAGE_RATIO = 0.8f;
    private static final int MIN_COLUMN_BOUNDARIES = 4;
    private static final int MAX_CONTINUATION_LINES = 8;

    @Override
    public NativeTableExtractionPolicy getPolicy() {
        return NativeTableExtractionPolicy.BOX_GUIDED;
    }

    @Override
    public List<Table> buildTables(NativePdfPageGeometry page) {
        List<Table> tables = new LinkedList<>();

        // column-boundary candidates: x-position stacks of vertical rulings
        // with a large, mostly continuous vertical coverage
        List<ColumnBoundary> candidates = new ArrayList<>();
        for (List<NativePdfRuling> cluster : clusterRulingsByPosition(page.getVerticalRulings(), POSITION_TOLERANCE)) {
            float top = clusterSpanStart(cluster);
            float bottom = clusterSpanEnd(cluster);
            float extent = bottom - top;
            if (extent < MIN_BOUNDARY_EXTENT) {
                continue;
            }
            float coverage = clusterCoverage(cluster, top, bottom);
            if (coverage >= extent * MIN_STACK_COVERAGE_RATIO) {
                candidates.add(new ColumnBoundary(clusterPosition(cluster), top, bottom, cluster));
            }
        }
        if (candidates.size() < MIN_COLUMN_BOUNDARIES) {
            return tables;
        }
        candidates.sort(Comparator.comparing(boundary -> boundary.x));

        // group boundaries by extent similarity (same top and bottom)
        List<List<ColumnBoundary>> groups = new ArrayList<>();
        boolean[] grouped = new boolean[candidates.size()];
        for (int i = 0; i < candidates.size(); i++) {
            if (grouped[i]) {
                continue;
            }
            ColumnBoundary seed = candidates.get(i);
            List<ColumnBoundary> group = new ArrayList<>();
            group.add(seed);
            grouped[i] = true;
            for (int j = i + 1; j < candidates.size(); j++) {
                if (grouped[j]) {
                    continue;
                }
                ColumnBoundary other = candidates.get(j);
                if (Math.abs(other.top - seed.top) <= EXTENT_GROUP_TOLERANCE
                        && Math.abs(other.bottom - seed.bottom) <= EXTENT_GROUP_TOLERANCE) {
                    group.add(other);
                    grouped[j] = true;
                }
            }
            groups.add(group);
        }

        List<BoxTable> boxTables = new ArrayList<>();
        for (List<ColumnBoundary> group : groups) {
            float top = median(group, boundary -> boundary.top);
            float bottom = median(group, boundary -> boundary.bottom);
            float height = bottom - top;
            if (height < MIN_BOUNDARY_EXTENT) {
                continue;
            }

            // extend the group with any boundary covering the box region
            // (outer border lines usually span several stacked boxes)
            TreeSet<Float> boundarySet = new TreeSet<>();
            for (ColumnBoundary candidate : candidates) {
                boolean member = group.contains(candidate);
                float coverage = clusterCoverage(candidate.rulings, top, bottom);
                if (member || coverage >= height * MIN_EXTENSION_COVERAGE_RATIO) {
                    boundarySet.add(candidate.x);
                }
            }
            if (boundarySet.size() < MIN_COLUMN_BOUNDARIES) {
                continue;
            }
            List<Float> boundaries = new ArrayList<>(boundarySet);
            float left = boundaries.get(0);
            float right = boundaries.get(boundaries.size() - 1);

            // rows from text lines inside the box region
            List<Word> regionWords = new ArrayList<>();
            for (Word word : page.getWords()) {
                float centerX = (word.getX1() + word.getX2() + word.getX3() + word.getX4()) / 4f;
                float centerY = (word.getY1() + word.getY2() + word.getY3() + word.getY4()) / 4f;
                if (centerX >= left && centerX <= right && centerY >= top - 0.02f && centerY <= bottom + 0.02f) {
                    regionWords.add(word);
                }
            }
            if (regionWords.isEmpty()) {
                continue;
            }

            List<TextRow> textRows = buildTextRows(regionWords);
            List<RowBand> rowBands = buildDateAnchoredRowBands(textRows, MAX_CONTINUATION_LINES);
            if (rowBands.isEmpty()) {
                // no date anchor inside the box (e.g. summary-only box)
                continue;
            }

            Table table = buildTable(page.getPageNumber(), boundaries, rowBands, page.getWords());
            if (table != null) {
                boxTables.add(new BoxTable(table, top, bottom, boundaries.size()));
            }
        }

        // when boxes overlap vertically (a narrower boundary group nested in
        // the same region), keep only the one with the most columns
        boxTables.sort(Comparator.comparing((BoxTable boxTable) -> boxTable.columnCount).reversed());
        List<BoxTable> kept = new ArrayList<>();
        for (BoxTable boxTable : boxTables) {
            boolean overlapsKept = false;
            for (BoxTable existing : kept) {
                float overlap = Math.min(existing.bottom, boxTable.bottom) - Math.max(existing.top, boxTable.top);
                float shorter = Math.min(existing.bottom - existing.top, boxTable.bottom - boxTable.top);
                if (shorter > 0f && overlap / shorter > 0.5f) {
                    overlapsKept = true;
                    break;
                }
            }
            if (!overlapsKept) {
                kept.add(boxTable);
            }
        }
        kept.sort(Comparator.comparing(boxTable -> boxTable.top));
        for (BoxTable boxTable : kept) {
            tables.add(boxTable.table);
        }

        return tables;
    }

    private interface FloatExtractor {
        float get(ColumnBoundary boundary);
    }

    private static float median(List<ColumnBoundary> box, FloatExtractor extractor) {
        List<Float> values = new ArrayList<>();
        for (ColumnBoundary boundary : box) {
            values.add(extractor.get(boundary));
        }
        values.sort(Comparator.naturalOrder());
        int size = values.size();
        if (size % 2 == 1) {
            return values.get(size / 2);
        }
        return (values.get(size / 2 - 1) + values.get(size / 2)) / 2f;
    }

    private static class ColumnBoundary {
        final float x;
        final float top;
        final float bottom;
        final List<NativePdfRuling> rulings;

        ColumnBoundary(float x, float top, float bottom, List<NativePdfRuling> rulings) {
            this.x = x;
            this.top = top;
            this.bottom = bottom;
            this.rulings = rulings;
        }
    }

    private static class BoxTable {
        final Table table;
        final float top;
        final float bottom;
        final int columnCount;

        BoxTable(Table table, float top, float bottom, int columnCount) {
            this.table = table;
            this.top = top;
            this.bottom = bottom;
            this.columnCount = columnCount;
        }
    }
}

